  function sanitizePythonFileName(name) {
    var value = String(name == null ? '' : name).replace(/^.*[\\/]/, '').trim();
    value = value.replace(/[^A-Za-z0-9_.-]+/g, '_').replace(/^_+|_+$/g, '');
    if (!value) value = 'file';
    if (!/\.py$/i.test(value)) value += '.py';
    if (value.length > 60) value = value.slice(0, 57) + '.py';
    return value;
  }

  function normalizePythonFiles(files, active) {
    var output = [];
    var used = Object.create(null);
    var source = Array.isArray(files) ? files : [];
    for (var i = 0; i < source.length && output.length < 20; i++) {
      var file = source[i];
      if (!file || typeof file.code !== 'string') continue;
      var name = sanitizePythonFileName(file.name || ('file' + (i + 1) + '.py'));
      var base = name.replace(/\.py$/i, '');
      var suffix = 2;
      while (used[name.toLowerCase()]) {
        name = base + '_' + suffix + '.py';
        suffix += 1;
      }
      used[name.toLowerCase()] = true;
      output.push({ name: name, code: file.code });
    }
    if (!output.length) output.push({ name: 'main.py', code: '' });
    var activeName = String(active || '');
    if (!output.some(function (file) { return file.name === activeName; })) {
      activeName = output[0].name;
    }
    return { files: output, active: activeName };
  }

